  467\t    return payload\n   468\t\n   469\t\n   470\tdef main() -> None:\n   471\t    today = date.today()\n   472\t    jobs = load_jobs(today)\n   473\t    jobs.sort(\n   474\t        key=lambda item: (\n   475\t            0 if item.effective_status == \"active\" else 1,\n   476\t            0 if item.meta.get(\"featured\") else 1,\n   477\t            -int(item.publish_date.strftime(\"%Y%m%d\")),\n   478\t            int(item.deadline.strftime(\"%Y%m%d\")),\n   479\t            item.meta[\"title\"],\n   480\t        )\n   481\t    )\n   482\t\n   483\t    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)\n   484\t    DATA_DIR.mkdir(parents=True, exist_ok=True)\n   485\t    FEED_DIR.mkdir(parents=True, exist_ok=True)\n   486\t\n   487\t    for job in jobs:\n   488\t        job.detail_path.write_text(render_detail_page(job), encoding=\"utf-8\")\n   489\t\n   490\t    payload = build_json_payload(jobs)\n   491\t    DATA_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding=\"utf-8\")\n   492\t    FEED_FILE.write_text(json.dumps(payload[:10], ensure_ascii=False, indent=2), encoding=\"utf-8\")\n   493\t    LIST_PAGE.write_text(render_list_page(jobs, today), encoding=\"utf-8\")\n   494\t\n   495\t    print(json.dumps(\n   496\t        {\n   497\t            \"jobs_total\": len(jobs),\n   498\t            \"jobs_active\": sum(1 for job in jobs if job.effective_status == \"active\"),\n   499\t            \"list_page\": str(LIST_PAGE.relative_to(ROOT)),\n   500\t            \"detail_dir\": str(OUTPUT_DIR.relative_to(ROOT)),\n   501\t            \"data_file\": str(DATA_FILE.relative_to(ROOT)),\n   502\t            \"feed_file\": str(FEED_FILE.relative_to(ROOT)),\n   503\t        },\n   504\t        ensure_ascii=False,\n   505\t        indent=2,\n   506\t    ))\n   507\t\n   508\t\n   509\tif __name__ == \"__main__\":\n   510\t    main()\n"}
