from pathlib import Path
import re
files=sorted(Path('content/tuyen-dung').glob('*.md'))
for p in files:
    if p.name in {'README.md','mau-tin-tuyen-dung.md'}:
        continue
    text=p.read_text(encoding='utf-8')
    title=re.search(r'^title:\s*(.+)$', text, re.M).group(1)
    summary=re.search(r'^summary:\s*(.+)$', text, re.M).group(1)
    flags=[]
    lower=title.lower()
    if 'kế toán trưởng' in lower and 'quản lý hệ thống kế toán' not in summary.lower(): flags.append('summary-mismatch-ke-toan-truong')
    if 'hành chính nhân sự' in lower and 'hành chính - nhân sự' not in summary.lower(): flags.append('summary-mismatch-hcns')
    if 'kế toán thuế' in lower and 'hồ sơ thuế' not in summary.lower(): flags.append('summary-mismatch-thue')
    if 'kế toán nội bộ' in lower and 'chứng từ nội bộ' not in summary.lower(): flags.append('summary-mismatch-noi-bo')
    if 'kế toán bán hàng' in lower and 'doanh thu' not in summary.lower(): flags.append('summary-mismatch-ban-hang')
    if flags:
        print(p.name, flags)
