from pathlib import Path
import re
root=Path('content/tuyen-dung')
affected=[]
for path in sorted(root.glob('*.md')):
    if path.name in {'README.md','mau-tin-tuyen-dung.md'}:
        continue
    text=path.read_text(encoding='utf-8')
    lines=text.splitlines()
    changed=False
    out=[]
    for line in lines:
        if line.startswith('- - '):
            body=line[4:].strip()
            parts=[p.strip(' -') for p in re.split(r'\s+-\s+', body) if p.strip(' -')]
            if len(parts) > 1:
                out.extend(f'- {part}' for part in parts)
            else:
                out.append('- ' + body)
            changed=True
        else:
            out.append(line)
    new='\n'.join(out)+'\n'
    if changed:
        path.write_text(new,encoding='utf-8')
        affected.append(path.name)
print('affected_count',len(affected))
for name in affected:
    print(name)
